BEGIN TRANSACTION;
CREATE TABLE ai_consultations (
    id TEXT PRIMARY KEY,
    consultation_id TEXT UNIQUE NOT NULL,
    mrn TEXT NOT NULL,
    patient_name TEXT,
    doctor_name TEXT,
    chief_complaint TEXT NOT NULL,
    organ_axis TEXT,
    mizaj TEXT,
    advisory_sections_json TEXT NOT NULL,
    citations_json TEXT NOT NULL,
    safety_verdict TEXT NOT NULL,
    provider_used TEXT NOT NULL,
    safe_to_lock INTEGER DEFAULT 0,
    facility_id TEXT DEFAULT "FAC-HQ-01",
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(facility_id) REFERENCES facilities(id)
);
INSERT INTO "ai_consultations" VALUES('AIC-001','AI-CONSULT-001','MRN-2026-0814','Hamza Farooqi','Prof. (Dr.) Mansoor Alam','Bilateral knee stiffness & joint ache in damp weather','mafasil-asab','Balghami (Cold & Moist)','{"CLINICAL SUMMARY": "62-year-old male with chronic knee joint stiffness (Waja-ul-Mafasil Barid Balghami).", "WHAT IS KNOWN": "Known case of osteoarthritis with cold-moist humoral dyscrasia.", "UNANI PERSPECTIVE": "Sluggish phlegmatic drainage along Mafasil-Asab triadic axis.", "BIOMEDICAL PERSPECTIVE": "Bilateral knee osteoarthrosis, radiological Kellgren-Lawrence Grade II.", "DIFFERENTIAL CONSIDERATIONS": "Waja-ul-Mafasil, Niqris (Gout), Osteoarthritis, Pseudogout.", "RED FLAGS": "None reported in current presentation. No acute septic arthritis.", "MISSING INFORMATION": "Recent serum uric acid and inflammatory markers (ESR/CRP).", "EVIDENCE": "UPI Monograph Vol I: Majun Suranjan & Suranjan Talkh Mudabbar indicated for joint arthralgia.", "SAFETY": "Schedule E(1) alkaloid (Colchicine). Mandatory Mudabbar certification required. Renal clearance monitoring advised.", "POSSIBLE CARE OPTIONS": "Majun Suranjan 5g nocte, Roghan Suranjan local application, Dalak Layyin regimen.", "MONITORING": "Follow-up at 14 days to assess VAS pain reduction and joint mobility.", "UNCERTAINTY": "Low uncertainty. Presentation concordant with classical descriptions.", "CLINICIAN REVIEW REQUIRED": "Yes \u2014 this AI advisory requires non-delegable clinician review before clinical action."}','[{"title": "Suranjan Talkh Monograph", "source": "Unani Pharmacopoeia of India (UPI) Vol 1", "part": "Dried corm", "schedule": "Schedule E(1)", "mudabbar": "Boiled in cow''s milk (Sheer-e-Gao)"}, {"title": "Majun Suranjan Classical Formulation", "source": "National Formulary of Unani Medicine (NFUM) Part I", "dosage": "5g post-prandial"}]','CAUTION','Primary (Anthropic Claude 3.5 Sonnet)',0,'FAC-HQ-01','2026-10-01 21:39:53');
INSERT INTO "ai_consultations" VALUES('AIC-DC5FC1A3','AI-CONSULT-660F9BEB','MRN-2026-0814','Hamza Farooqi','Prof. (Dr.) Mansoor Alam','Subacute knee swelling with phlegmatic dyscrasia (Su-ul-Mizaj Barid Balghami)','Musculoskeletal-Metabolic Axis (Mafasil-Asab)','Balghami (Cold & Moist)','{"CLINICAL SUMMARY": "Patient presenting with: Subacute knee swelling with phlegmatic dyscrasia (Su-ul-Mizaj Barid Balghami). Dominant constitution assessed as Balghami (Cold & Moist).", "WHAT IS KNOWN": "Known symptoms and functional impairment along the Musculoskeletal-Metabolic Axis (Mafasil-Asab). Medications: None documented.", "UNANI PERSPECTIVE": "Presentation concordant with Waja-ul-Mafasil Barid Balghami (Cold-Moist Phlegmatic Arthralgia) along the Musculoskeletal-Metabolic Axis (Mafasil-Asab). Humoral stasis impairs synovial lubrication.", "BIOMEDICAL PERSPECTIVE": "Osteoarthritis with secondary synovial inflammation. Differential must exclude Gouty Arthritis (Niqris) and early Seronegative Spondylopathy.", "DIFFERENTIAL CONSIDERATIONS": "Waja-ul-Mafasil, Osteoarthritis (ICD-10 M17.9), Niqris (Gout, ICD-10 M10.9), Pseudogout.", "RED FLAGS": "None documented in current presentation. Immediate biomedical referral required if red flags develop.", "MISSING INFORMATION": "Recent serum uric acid, inflammatory markers (ESR, hs-CRP), and bilateral weight-bearing radiographs.", "EVIDENCE": "UPI Monograph Vol I: Suranjan Talkh (Colchicum luteum) and Majun Suranjan indicated for joint inflammation with verified analgesic efficacy.", "SAFETY": "Patient medications on file: None documented. Allergies: Sonf (Foeniculum vulgare). Full deterministic Safety Firewall verification required before prescription lock.", "POSSIBLE CARE OPTIONS": "Majun Suranjan 5g nocte with warm milk; Roghan Suranjan local application; Dalak Layyin (gentle massage) regimen.", "MONITORING": "Clinical review and PROMs symptom score evaluation in 14 days or earlier if acute exacerbation occurs.", "UNCERTAINTY": "Low to moderate uncertainty. Clinical impression grounded in classical Unani texts (Al-Qanun fi al-Tibb, Kitab al-Hawi) and UPI monographs.", "CLINICIAN REVIEW REQUIRED": "Yes \u2014 this clinical guidance is synthesized by ZAYVORA Hakeem Sahab\u2122 for decision-support purposes only. In accordance with clinical governance standards, this recommendation requires non-delegable review and digital signature by a licensed practitioner before any clinical action is taken."}','[{"title": "Classical Monograph", "source": "Unani Pharmacopoeia of India (UPI) Vol 1", "temperament": {"temperament": "Safrawi", "quality": "Hot & Dry", "hc_degree": 3, "wd_degree": 3}, "evidence_level": "E0 (Canonical Textual Monograph)"}]','SAFE_TO_CONSIDER','Deterministic Classical Unani Knowledge Fallback',0,'FAC-HQ-01','2026-10-01 21:39:55');
INSERT INTO "ai_consultations" VALUES('AIC-9C7D9670','AI-CONSULT-6746AE9E','MRN-2026-0814','Hamza Farooqi','Prof. (Dr.) Mansoor Alam','Persistent bilateral knee stiffness and dull pain in cold rainy weather','mafasil-asab','Balghami (Cold & Moist)','{"CLINICAL SUMMARY": "Patient presenting with: Persistent bilateral knee stiffness and dull pain in cold rainy weather. Dominant constitution assessed as Balghami (Cold & Moist).", "WHAT IS KNOWN": "Known symptoms and functional impairment along the mafasil-asab. Medications: None documented.", "UNANI PERSPECTIVE": "Presentation concordant with Waja-ul-Mafasil Barid Balghami (Cold-Moist Phlegmatic Arthralgia) along the mafasil-asab. Humoral stasis impairs synovial lubrication.", "BIOMEDICAL PERSPECTIVE": "Osteoarthritis with secondary synovial inflammation. Differential must exclude Gouty Arthritis (Niqris) and early Seronegative Spondylopathy.", "DIFFERENTIAL CONSIDERATIONS": "Waja-ul-Mafasil, Osteoarthritis (ICD-10 M17.9), Niqris (Gout, ICD-10 M10.9), Pseudogout.", "RED FLAGS": "None documented in current presentation. Immediate biomedical referral required if red flags develop.", "MISSING INFORMATION": "Recent serum uric acid, inflammatory markers (ESR, hs-CRP), and bilateral weight-bearing radiographs.", "EVIDENCE": "UPI Monograph Vol I: Suranjan Talkh (Colchicum luteum) and Majun Suranjan indicated for joint inflammation with verified analgesic efficacy.", "SAFETY": "Patient medications on file: None documented. Allergies: Sonf (Foeniculum vulgare). Full deterministic Safety Firewall verification required before prescription lock.", "POSSIBLE CARE OPTIONS": "Majun Suranjan 5g nocte with warm milk; Roghan Suranjan local application; Dalak Layyin (gentle massage) regimen.", "MONITORING": "Clinical review and PROMs symptom score evaluation in 14 days or earlier if acute exacerbation occurs.", "UNCERTAINTY": "Low to moderate uncertainty. Clinical impression grounded in classical Unani texts (Al-Qanun fi al-Tibb, Kitab al-Hawi) and UPI monographs.", "CLINICIAN REVIEW REQUIRED": "Yes \u2014 this clinical guidance is synthesized by ZAYVORA Hakeem Sahab\u2122 for decision-support purposes only. In accordance with clinical governance standards, this recommendation requires non-delegable review and digital signature by a licensed practitioner before any clinical action is taken."}','[{"title": "Classical Monograph", "source": "Unani Pharmacopoeia of India (UPI) Vol 1", "temperament": {"temperament": "Safrawi", "quality": "Hot & Dry", "hc_degree": 3, "wd_degree": 3}, "evidence_level": "E0 (Canonical Textual Monograph)"}]','SAFE_TO_CONSIDER','Deterministic Classical Unani Knowledge Fallback',0,'FAC-HQ-01','2026-10-01 21:39:56');
