CREATE TABLE clinical_assessments (
    assessment_id TEXT PRIMARY KEY,
    encounter_id TEXT NOT NULL,
    patient_id TEXT NOT NULL,
    clinician_id TEXT NOT NULL,
    subjective_narrative TEXT,
    objective_findings_json TEXT,             -- Vitals, Nabz, Lisan, physical examination
    assessment_summary TEXT NOT NULL,
    plan_summary TEXT NOT NULL,
    inputs_reproducibility_json TEXT NOT NULL, -- Raw patient data used to derive scores
    confidence_score REAL NOT NULL DEFAULT 1.0,
    immutable_sha256_hash TEXT NOT NULL,
    signed_at DATETIME NOT NULL,
    FOREIGN KEY(encounter_id) REFERENCES encounters(id),
    FOREIGN KEY(patient_id) REFERENCES patients(id),
    FOREIGN KEY(clinician_id) REFERENCES clinician_registry(clinician_id)
);
CREATE TABLE clinician_registry (
    clinician_id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL UNIQUE,
    registration_number TEXT NOT NULL UNIQUE,
    registration_body TEXT NOT NULL,          -- e.g. NCISM, State Board of Unani Medicine, Delhi Bharatiya Chikitsa Parishad
    registration_state TEXT NOT NULL,
    registration_type TEXT NOT NULL,          -- PERMANENT, PROVISIONAL, RENEWAL
    specialty TEXT NOT NULL,                  -- UNANI_MEDICINE, ILMUL_ADVIA, MOALAJAT, INTEGRATIVE_MEDICINE
    qualification TEXT NOT NULL,              -- BUMS, MD (Unani), MBBS, MS
    facility_scope TEXT NOT NULL,             -- ALL, or comma-separated facility IDs
    clinical_scope TEXT NOT NULL,             -- GENERAL_PRACTICE, CONSULTANT_TABEEB, PHARMACOLOGY_CHIEF
    issued_at DATE NOT NULL,
    expires_at DATE NOT NULL,
    verification_status TEXT NOT NULL,        -- VERIFIED_ACTIVE, SUSPENDED, EXPIRED, PENDING_REVIEW
    verified_by TEXT NOT NULL,
    verified_at DATETIME NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id)
);
INSERT INTO "clinician_registry" VALUES('CLN-IRFAN-01','USR-DOC-REQ1','Reg. No: (Updating / Verification in Progress)','Board of Ayurvedic and Unani Systems of Medicine / NCISM','Delhi','PERMANENT','UNANI_MEDICINE','BUMS (AKTC Aligarh Muslim University, Batch 2002, Passed 2007)','ALL','CONSULTANT_TABEEB','2007-06-15','2030-06-14','UPDATING_VERIFICATION','REGISTRAR_NCISM','2026-01-10 10:00:00');
INSERT INTO "clinician_registry" VALUES('CLN-MANSOOR-02','DOC-01','UP-UNANI-2012-08819','Uttar Pradesh Board of Indian Medicine / NCISM','Uttar Pradesh','PERMANENT','MOALAJAT','BUMS','FAC-HQ-01','CONSULTANT_TABEEB','2012-04-20','2028-04-19','VERIFIED_ACTIVE','REGISTRAR_NCISM','2026-01-10 10:00:00');
INSERT INTO "clinician_registry" VALUES('CLN-MALIK-03','USR-DOC-REQ2','TEL-UNANI-2020-03310','Telangana Board of Indian Medicine / NCISM','Telangana','PERMANENT','UNANI_MEDICINE','BUMS','FAC-BRANCH-02','GENERAL_PRACTICE','2020-08-11','2027-08-10','VERIFIED_ACTIVE','REGISTRAR_NCISM','2026-01-10 10:00:00');
CREATE TABLE encounters (
    id TEXT PRIMARY KEY,
    encounter_number TEXT UNIQUE NOT NULL,
    mrn TEXT NOT NULL,
    patient_name TEXT NOT NULL,
    appointment_id TEXT,
    doctor_name TEXT NOT NULL,
    doctor_reg TEXT NOT NULL,
    facility_id TEXT DEFAULT "FAC-HQ-01",
    chief_complaint TEXT,
    examination_notes TEXT,
    vitals_json TEXT DEFAULT "{}",
    soap_json TEXT DEFAULT "{}",
    mizaj_json TEXT DEFAULT "{}",
    organ_axis_json TEXT DEFAULT "{}",
    afaal_cascade_json TEXT DEFAULT "{}",
    prescription_id TEXT,
    status TEXT DEFAULT "IN_PROGRESS", -- IN_PROGRESS, LOCKED_AND_SIGNED, CANCELLED
    signature_hash TEXT,
    started_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    signed_at DATETIME,
    FOREIGN KEY(facility_id) REFERENCES facilities(id),
    FOREIGN KEY(appointment_id) REFERENCES appointments(id),
    FOREIGN KEY(prescription_id) REFERENCES prescriptions(id)
);
INSERT INTO "encounters" VALUES('ENC-001','ENC-2026-0814','MRN-2026-0814','Hamza Farooqi','APT-104','Prof. (Dr.) Mansoor Alam','CCIM-U-1988-0412','FAC-HQ-01','Bilateral knee stiffness & joint ache in damp weather','Nabz: Bat''ee, Layyin. Lisan: Rutubat-e-Ghaliba. Joints: Mild crepitus, no acute erythema.','{"bp": "124/82", "pulse": "72", "temp": "98.4", "weight": "78", "spo2": "98", "hrv": "46.2"}','{"subjective": "Bilateral knee pain and morning stiffness (>45 min) aggravated by damp cold weather.", "objective": "Nabz: Bat''ee, Layyin. Lisan: Rutubat-e-Ghaliba, whitish fur. Patellofemoral crepitus present.", "assessment": "Waja-ul-Mafasil Barid Balghami (Osteoarthritis / Phlegmatic Arthropathy - ICD-11: FA00).", "plan": "Stage 2 Tahleel: Majun Suranjan 5g bd + Roghan Balsan local application + Nutool Haar."}','{"dominant": "Balghami (Cold & Moist)", "secondary": "Damawi", "su_e_mizaj": "Su-e-Mizaj Barid Balghami", "dyscrasia_degree": 2}','{"primary_axis": "Brain-Liver-Joint Triadic Axis", "status": "IMPAIRED_DRAINAGE", "rationale": "Phlegmatic humor congestion in synovial joints with sluggish systemic clearance."}','{"current_stage": "TAHLEEL", "goals": ["Resolve morning knee stiffness to <15 min", "Reduce synovial fullness", "Achieve >40% VAS pain relief"], "regimen": "Nutool Haar with warm decoction for 10 minutes daily"}','RX-001','LOCKED_AND_SIGNED','731f5cf53472e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495','2026-10-01 21:39:53',NULL);
INSERT INTO "encounters" VALUES('ENC-7DBDE2','ENC-2026-92A0','MRN-2026-0006','Zubair Khan','APT-2ACEC7','Prof. (Dr.) Mansoor Alam','CCIM-U-1988-0412','FAC-HQ-01','Sub-acute lumbar stiffness with damp aggravation','Nabz: Bat''ee, Layyin. Lisan: White fur.','{"bp": "126/84", "pulse": "74", "temp": "98.6", "weight": "82", "spo2": "99", "hrv": "48.5"}','{"subjective": "Lumbar stiffness lasting >30 minutes in morning. Aggravated by rainy/cold weather.", "objective": "Nabz: Bat''ee, Layyin. Lisan: Rutubat-e-Ghaliba with white coating. Lumbar paraspinal tightness without radiation.", "assessment": "Waja-ul-Zahr Barid Balghami (Lumbago / Phlegmatic Myofascial Pain).", "plan": "Stage 1 Tanqiya: Munzij & Mushil Balgham followed by Stage 2 Tahleel with Roghan Suranjan."}','{"dominant": "Balghami (Cold & Moist)", "answers": {"touch": "cold", "moisture": "moist", "build": "broad", "sleep": "excessive"}}','{"primary_axis": "Musculoskeletal-Metabolic Axis", "status": "IMPAIRED_DRAINAGE", "rationale": "Accumulation of phlegmatic matter in lumbosacral aponeurosis."}','{"current_stage": "TANQIYA", "goals": ["Relieve morning stiffness to <10 min", "Reduce muscular spasm"], "regimen": "Nutool Haar with warm chamomile infusion nocte"}',NULL,'LOCKED_AND_SIGNED','bbe014e8d0a4ddd4ddad7a6dd250606e97b7a3663f67392c60bfae79ab1e25af','2026-10-01 21:39:56','2026-10-01T21:39:56.565872Z');
INSERT INTO "encounters" VALUES('ENC-097AAB','ENC-2026-05CC','MRN-2026-0007','Hakim Ajmal','APT-843973','Prof. (Dr.) Mansoor Alam','CCIM-U-1988-0412','FAC-HQ-01','Sub-acute knee stiffness with cold aggravation','Nabz: Qawi, Imtila. Lisan: Normal.','{"bp": "120/80", "pulse": "72", "temp": "98.6"}','{"subjective": "Bilateral knee stiffness in morning.", "objective": "No crepitus, Nabz imtila.", "assessment": "Waja-ul-Mafasil Damwi.", "plan": "Tanqiya followed by Tadeel."}','{"dominant": "Balghami (Cold & Moist)", "answers": {"touch": "cold", "moisture": "moist", "build": "broad", "sleep": "excessive"}}','{"primary_axis": "Musculoskeletal Axis", "status": "ACTIVE"}','{"current_stage": "TANQIYA", "goals": ["Relieve stiffness"]}',NULL,'LOCKED_AND_SIGNED','a44f8b2eedc91fa04603996e717094da19d43afd4e4330d7074f73fef2b9d295','2026-10-01 21:39:57','2026-10-01T21:39:57.374300Z');
CREATE TABLE evidence_claims (
    claim_id TEXT PRIMARY KEY,
    source_id TEXT NOT NULL,
    canonical_substance_id TEXT,
    page_number INTEGER,
    passage_text TEXT NOT NULL,
    evidence_tier TEXT NOT NULL,              -- E0, E1, E2, E3, E4, E5, E6
    study_design TEXT,
    population_size INTEGER,
    confidence_score REAL NOT NULL,
    verified_by TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(source_id) REFERENCES evidence_sources(source_id)
);
CREATE TABLE evidence_sources (
    source_id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    edition TEXT,
    publication_year INTEGER,
    isbn_or_doi TEXT,
    source_type TEXT NOT NULL,                -- PHARMACOPOEIA, CLASSICAL_CANON, PEER_REVIEWED_RCT, META_ANALYSIS, OBSERVATIONAL
    jurisdiction TEXT DEFAULT "INDIA",        -- INDIA, WHO, EMA, US_FDA
    digital_sha256_checksum TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
