    primary_products TEXT,
    regulatory_track TEXT,
    description TEXT
);
INSERT INTO "master_organ_axes" VALUES('Qalb-Uroq','قلب و عروق','Cardio-Vascular','Quwwat-e-Haiwaniyah (Vital Faculty)','["Hypertension", "Ischaemic Heart Disease (IHD)", "Palpitations", "Arrhythmia"]','["HyperCalm", "CardioGuard", "LipidClear"]','AYUSH preferred','Cardiovascular and vascular network governing circulation, blood pressure, and arterial elasticity.');
INSERT INTO "master_organ_axes" VALUES('Jigar-Banas','جگر و بنقراس','Hepato-Metabolic','Quwwat-e-Tabi''iyah (Natural/Metabolic Faculty)','["Diabetes Type 2", "NAFLD", "Fatty Liver", "Metabolic Syndrome", "Insulin Resistance"]','["DiabEase", "HepaClear", "LipidClear", "MetaboBurn-M"]','FSSAI/AYUSH','Hepatic and pancreatic metabolic axis regulating glucose homeostasis, glycogen storage, and intermediate metabolism.');
INSERT INTO "master_organ_axes" VALUES('Dimagh-Qalb','دماغ و قلب','Neuro-Cardiac','Quwwat-e-Nafsaniyah wa Haiwaniyah (Neuro-Vital Faculty)','["Anxiety", "Depression", "Insomnia", "Stress", "Burnout", "Cardioneurosis"]','["MindBalance", "Sleep+Stress"]','FSSAI/AYUSH','Central nervous system, HPA axis, and cardiac autonomic interface governing emotional and sleep regulation.');
INSERT INTO "master_organ_axes" VALUES('Riya-Sadr','ریہ و صدر','Respiratory','Quwwat-e-Tanaffusiyah (Respiratory Faculty)','["Asthma", "COPD", "Allergic Rhinitis", "Bronchitis", "Mucosal Congestion"]','["LungEase", "Immunity"]','FSSAI','Bronchopulmonary network and thoracic mucosal barrier providing oxygenation and phlegm clearance.');
INSERT INTO "master_organ_axes" VALUES('Mafasil-Dam','مفاصل و دم','Musculo-Skeletal','Quwwat-e-Masika wa Muharrika (Holding & Locomotor Faculty)','["Osteoarthritis (OA)", "Rheumatoid Arthritis (RA)", "Gout", "Joint Inflammation"]','["JointFree"]','FSSAI','Joints, cartilage matrix, synovial fluid, and circulating inflammatory mediators.');
INSERT INTO "master_organ_axes" VALUES('Khusyatain-Dam','خصیتین و دم','Male Reproductive','Quwwat-e-Tawalludiyah (Generative Faculty)','["Erectile Dysfunction (ED)", "Oligospermia", "Low Testosterone", "Male Infertility", "DNA Fragmentation"]','["VigorX-ED", "TestoVital Classic", "Fertility PRO", "FertiMax-M"]','AYUSH/FSSAI','Testicular Leydig and Sertoli cell network, spermatogenesis, and androgenic hormone cascade.');
INSERT INTO "master_organ_axes" VALUES('Reham-Mabaysim','رحم و مبایض','Female Reproductive','Quwwat-e-Tanasuliyya Niswaniyah (Female Generative Faculty)','["PCOS", "Leucorrhoea", "Menstrual Disorders (Dysmenorrhoea/Menorrhagia)", "Menopause"]','["CycloCare-PCOS", "FertiliWomen", "LeucoClear", "MenoPease"]','FSSAI/AYUSH','Uterine-ovarian axis governing folliculogenesis, endometrial integrity, and menstrual cycle synchrony.');
INSERT INTO "master_organ_axes" VALUES('Meda-Amaa','معدہ و امعاء','GI System','Quwwat-e-Hazima wa Dafia (Digestive & Expulsive Faculty)','["IBS", "Chronic Constipation", "Bloating", "Gut Dysbiosis", "Leaky Gut", "SIBO"]','["GutEase-IBS", "HepaClear"]','FSSAI','Gastrointestinal tract, enteric nervous system, mucosal barrier, and gut microbiome.');
INSERT INTO "master_organ_axes" VALUES('Ghudad-Hazm','غدد و ہضم','Endocrine / Thyroid','Quwwat-e-Mughayyira (Transformative Metabolic Faculty)','["Hypothyroidism", "Subclinical Hypothyroidism", "Low T3 Syndrome", "Metabolic Dysregulation"]','["ThyroMet-W", "MindBalance"]','FSSAI','Thyroid gland and hepatic deiodinase enzymatic axis regulating cellular metabolic rate.');
INSERT INTO "master_organ_axes" VALUES('Ghudda-Mithana','غدہ و مثانہ','Prostate-Urinary','Quwwat-e-Dafia (Urinary Excretory Faculty)','["BPH", "LUTS (Lower Urinary Tract Symptoms)", "Urinary Stones (Hisat-e-Kulya)", "UTI"]','["ProstaGuard", "UroClear"]','FSSAI','Prostate gland, renal pelvis, ureters, and urinary bladder.');
INSERT INTO "master_organ_axes" VALUES('Shaar-Jigar','شعر و جگر','Hair-Systemic','Quwwat-e-Ghazia (Nutritive Hair Follicle Faculty)','["Androgenic Alopecia (Male/Female)", "Telogen Effluvium", "DHT Excess", "Stress Hair Loss"]','["HairRoot-X"]','FSSAI','Dermal hair follicles, scalp microcirculation, and hepatic nutrient-androgen regulatory balance.');
INSERT INTO "master_organ_axes" VALUES('Tabiyat','طبیعت و مناعت','Immune System','Quwwat-e-Mudabbira-e-Badan (Innate Healing Intelligence)','["Recurrent Infections", "Post-Viral Fatigue", "Immunodeficiency", "Inflammatory Diathesis"]','["Immunity"]','FSSAI','Innate and adaptive immune network, macrophage phagocytosis, T-cell regulation, and biological resilience.');
CREATE TABLE master_parhez (
    code TEXT PRIMARY KEY,
    name TEXT,
    classical_principle TEXT,
    target_axes TEXT,
    duration_days INTEGER,
    rules TEXT
);
INSERT INTO "master_parhez" VALUES('MF-01','Male Fertility & Spermatogenesis Parhez','Hifz-e-Mani & Taskeen-e-Hararat-e-Khusyatain (Preservation of Semen & Testicular Cooling)','["ANDROLOGICAL"]',90,'[{"category": "Thermal Regulation", "instruction": "Strict testicular cooling: Wear 100% loose breathable cotton boxer shorts. Strictly avoid hot tubs, thermal baths, saunas, and resting laptop directly on lap.", "scientific_rationale": "Spermatogenic enzymes undergo denaturation at temperatures above 34.5\u00b0C; elevated scrotal heat directly increases DNA fragmentation index."}, {"category": "Circadian & Sleep", "instruction": "Sleep strictly between 10:00 PM and 6:00 AM (8 continuous hours in total darkness).", "scientific_rationale": "Peak nocturnal melatonin secretion scavenges reactive oxygen species in testicular Leydig and Sertoli cells."}, {"category": "Toxicology & Abstinence", "instruction": "Zero alcohol, zero cigarette/tobacco/vape nicotine, zero recreational drugs for minimum 90-120 days.", "scientific_rationale": "Nicotine and ethanol induce testicular microvascular ischemia and profound teratozoospermia."}, {"category": "Nutritional Additions", "instruction": "Consume 30g raw walnuts daily and wild oily fish (or flaxseed + algae DHA) 3 times weekly.", "scientific_rationale": "Alpha-linolenic acid (ALA) and DHA integrate into sperm plasma membrane, restoring vital membrane fluidity and progressive motility."}, {"category": "Autonomic Nervous System", "instruction": "Perform 4-7-8 breathing exercises (Inhale 4s, Hold 7s, Exhale 8s) for 10 minutes twice daily.", "scientific_rationale": "Vagal nerve stimulation reduces sympathetic vasoconstriction to internal pudendal and testicular arteries."}]');
INSERT INTO "master_parhez" VALUES('PC-01','PCOS Lifestyle & Insulin Reset Parhez','Tanqia-e-Balgham & Fath-e-Sudad-e-Reham (Phlegm Decongestion & Uterine De-obstruction)','["GYNECOLOGICAL", "METABOLIC"]',180,'[{"category": "Carbohydrate Architecture", "instruction": "Eliminate all refined sugars, white flour, fruit juices, and high-glycemic starches (daily glycemic load < 45).", "scientific_rationale": "Hyperinsulinemia directly stimulates the ovarian theca cells to overproduce androgens and suppresses hepatic SHBG."}, {"category": "Dairy Modulation", "instruction": "Restrict conventional dairy to <= 1 serving per day of A2 fermented kefir or sheep/goat yogurt.", "scientific_rationale": "Insulin-like growth factor-1 (IGF-1) present in commercial bovine dairy exacerbates follicular arrest and cystic transformation."}, {"category": "Physical Resistance", "instruction": "Perform 3 sessions weekly of progressive strength resistance training (compound multi-joint exercises).", "scientific_rationale": "Skeletal muscle GLUT-4 translocation occurs independently of insulin during resistance contraction, dramatically reducing systemic insulin resistance."}, {"category": "Postprandial Protocol", "instruction": "Undertake a 15-20 minute brisk walk immediately following the two main meals of the day.", "scientific_rationale": "Post-meal light ambulation attenuates peak postprandial glucose excursions by up to 35%."}, {"category": "Pelvic Circulation", "instruction": "Apply warm castor oil packs over the lower abdomen for 45 minutes, 3 times weekly (strictly outside of menstrual bleeding days).", "scientific_rationale": "Ricinoleic acid promotes local lymphatic drainage and softens congested pelvic adhesions."}]');
INSERT INTO "master_parhez" VALUES('TM-01','Thyroid-Metabolic Circadian Reset Parhez','In''ash-e-Hararat-e-Ghariziya (Revival of Innate Metabolic Heat)','["ENDOCRINE", "METABOLIC"]',120,'[{"category": "Morning Photobiology", "instruction": "Expose eyes and face to outdoor natural sunlight within 30 minutes of waking for 10-15 minutes.", "scientific_rationale": "Photonic entrainment of the suprachiasmatic nucleus (SCN) coordinates the hypothalamic TRH and pituitary TSH pulsatility."}, {"category": "Thermal Dietetics", "instruction": "Consume exclusively warm, cooked, aromatic foods; avoid raw refrigerated meals and ice-cold water.", "scientific_rationale": "Conserves digestive enzymatic energy (*Hararat-e-Ghariziya*) and prevents gastrointestinal transit sluggishness."}, {"category": "Goitrogen Deactivation", "instruction": "All cruciferous vegetables (broccoli, cabbage, cauliflower, kale) must be thoroughly steamed or boiled before consumption.", "scientific_rationale": "Thermal cooking deactivates myrosinase enzymes, preventing the release of goitrin which competitively inhibits thyroidal iodide uptake."}, {"category": "Trace Mineral Fortification", "instruction": "Eat exactly 2 Brazil nuts daily (provides 100-200 mcg organic selenomethionine).", "scientific_rationale": "Selenium is the essential cofactor for iodothyronine deiodinase enzymes responsible for converting inactive T4 to bioactive T3."}, {"category": "Supplement Caution", "instruction": "Do not consume high-dose iodine or kelp supplements unless specifically prescribed by a physician.", "scientific_rationale": "Excessive iodine can precipitate the Wolff-Chaikoff effect or trigger severe autoimmune thyroid flares in Hashimoto''s patients."}]');
INSERT INTO "master_parhez" VALUES('NE-01','Neuro-Sleep & Cortisol Reset Parhez','Taskeen-e-Ruh & Ta''deel-e-Khafqan (Calming of Vital Spirit & Nervous Equilibrium)','["NEUROPSYCHIATRIC"]',60,'[{"category": "Digital Sunset", "instruction": "Implement strict digital curfew at 9:00 PM: All LED screens, phones, laptops, and bright overhead blue lighting powered off.", "scientific_rationale": "Short-wavelength 480nm blue light suppresses pineal melatonin secretion and maintains evening cortisol elevation."}, {"category": "Circadian Consistency", "instruction": "Maintain an identical bedtime and wake time 7 days a week within a maximum variance of +/- 30 minutes.", "scientific_rationale": "Consistent sleep schedules stabilize the central circadian pacemaker and consolidate restorative slow-wave delta sleep."}, {"category": "Adenosine Clearance & Caffeine", "instruction": "Absolute zero caffeine (coffee, black tea, energy drinks, colas) after 12:00 PM noon.", "scientific_rationale": "Caffeine has a 5-7 hour half-life; competitive blockade of adenosine A1 receptors in the ventrolateral preoptic nucleus impedes sleep architecture."}, {"category": "Thermal Pre-Sleep Protocol", "instruction": "Take a warm shower or foot soak with Epsom salts (magnesium sulfate) 60 minutes before bed.", "scientific_rationale": "Peripheral vasodilation causes rapid core body temperature cooling, which is the physiological trigger for sleep onset."}]');
INSERT INTO "master_parhez" VALUES('WM-01','Metabolic Reset & Weight Optimization Parhez','Qat-e-Shahm & Taqlil-e-Ghiza (Adipose Dissolution & Caloric Restraint)','["METABOLIC", "HEPATOBILIARY"]',90,'[{"category": "Time-Restricted Feeding", "instruction": "Adopt a 16:8 Intermittent Fasting schedule with daily eating window strictly from 12:00 PM to 8:00 PM.", "scientific_rationale": "16 hours of daily fasting lowers circulating insulin, triggers hepatic autophagy, and upregulates fatty acid beta-oxidation."}, {"category": "Refined Calorie Elimination", "instruction": "Strictly eliminate all refined grains, seed oils (sunflower, soybean, corn), and commercial snacks.", "scientific_rationale": "High omega-6 to omega-3 ratios promote chronic macrophage infiltration of visceral adipose tissue and systemic inflammation."}, {"category": "Daily Non-Exercise Physical Activity", "instruction": "Achieve a minimum of 10,000 steps daily distributed across morning, afternoon, and evening.", "scientific_rationale": "Non-Exercise Activity Thermogenesis (NEAT) accounts for the largest fraction of variable daily energy expenditure."}, {"category": "Hydration Volume", "instruction": "Drink 35 ml per kg body weight of warm or ambient temperature water throughout daylight hours.", "scientific_rationale": "Adequate cellular hydration prevents misinterpretation of thirst as hunger and assists renal elimination of metabolic end-products."}]');
INSERT INTO "master_parhez" VALUES('FK-01','Hepatobiliary Reset & Fatty Liver Parhez','Tanqia-e-Jigar & Daf-e-Dasaumat (Hepatic Decontamination & Lipid Washout)','["HEPATOBILIARY", "METABOLIC"]',180,'[{"category": "Fructose Abstinence", "instruction": "Strictly eliminate all industrial high-fructose corn syrup, sweetened beverages, honey in large amounts, and fruit juices.", "scientific_rationale": "Hepatic fructokinase metabolizes fructose unrestrained by ATP negative feedback, converting it directly into toxic intrahepatic triglycerides via de novo lipogenesis."}, {"category": "Absolute Alcohol Abstinence", "instruction": "Zero alcohol intake for a minimum of 180 days.", "scientific_rationale": "Ethanol induces mitochondrial reactive oxygen species in hepatocytes and accelerates progression from steatosis to steatohepatitis (MASH)."}, {"category": "Bioactive Coffee Consumption", "instruction": "Consume 2 cups of unsweetened black filtered coffee daily (unless contraindicated by severe cardiac arrhythmia).", "scientific_rationale": "Caffeine and chlorogenic acid stimulate hepatic autophagy and are clinically demonstrated to reduce liver stiffness and fibrosis scores."}, {"category": "Bitter Botanical Dietetics", "instruction": "Incorporate daily bitter greens: Cichorium (Kasni), dandelion greens, mustard greens, arugula, or fresh radish.", "scientific_rationale": "Bitters stimulate cholecystokinin release, enhance bile acid excretion, and decongest intrahepatic biliary canaliculi."}, {"category": "Protein Sourcing", "instruction": "Limit red meat to <= 1 serving every 2 weeks; prioritize wild fish, lentils, and sprouted pulses.", "scientific_rationale": "High intake of saturated fat and heme iron in red meat increases hepatic oxidative stress and worsens insulin resistance."}]');
INSERT INTO "master_parhez" VALUES('ST-01','Nephrolithiasis (StoneGuard) Parhez','Taflis-e-Hisat & Tanqia-e-Majari-e-Baul (Stone Fragmentation & Urinary Tract Cleansing)','["UROLOGICAL"]',90,'[{"category": "Hydration Target", "instruction": "Drink at least 2.5 to 3.0 Liters of water daily to maintain a 24-hour urine output exceeding 2.0 Liters.", "scientific_rationale": "Dilution decreases urinary supersaturation of calcium oxalate, uric acid, and calcium phosphate below crystallization thresholds."}, {"category": "Citrate Alkalinization", "instruction": "Drink freshly squeezed lemon juice (from 2 whole lemons) in warm water twice daily.", "scientific_rationale": "Citrate binds free calcium in the urinary lumen, forming a soluble calcium citrate complex and inhibiting crystal nucleation and agglomeration."}, {"category": "Oxalate Modulation", "instruction": "Restrict high-oxalate foods: Avoid spinach, Swiss chard, rhubarb, beets, dark chocolate, and excessive almonds.", "scientific_rationale": "Hyperoxaluria is a potent driver of calcium oxalate monohydrate (whewellite) stone precipitation."}, {"category": "Calcium Maintenance", "instruction": "Do NOT restrict dietary calcium; consume normal dietary calcium (yogurt, paneer, sesame) with meals.", "scientific_rationale": "Dietary calcium binds free oxalate in the gastrointestinal tract, forming insoluble calcium oxalate that is excreted in feces rather than absorbed into circulation."}, {"category": "Sodium Restriction", "instruction": "Limit dietary sodium intake to < 2000 mg/day (under 1 level teaspoon of table salt).", "scientific_rationale": "High proximal tubular sodium reabsorption is linked to calcium excretion; reducing sodium decreases urinary calcium excretion."}]');
INSERT INTO "master_parhez" VALUES('Resp-01','Pulmonary & Airway Decongestion Parhez','Tanqiya-e-Sadr & Tahleel-e-Balgham (Chest Clearance & Phlegm Liquefaction)','["PULMONARY"]',60,'[{"category": "Mucogenic Food Avoidance", "instruction": "Eliminate cold milk, ice cream, aged cheeses, deep-fried snacks, and heavy sour curds.", "scientific_rationale": "Cold temperature and dairy casein increase oropharyngeal and tracheobronchial mucus viscosity in susceptible individuals."}, {"category": "Warm Demulcent Hydration", "instruction": "Sip warm water infused with fresh ginger, tulsi leaves, and licorice throughout the day.", "scientific_rationale": "Warm fluids enhance tracheobronchial ciliary beat frequency and promote mucociliary clearance."}, {"category": "Inhalational Aromatherapy", "instruction": "Perform steam inhalation with 2 drops of eucalyptus oil or mint extract for 10 minutes each evening before sleep.", "scientific_rationale": "Volatile cineole and menthol act on TRPM8 sensory receptors to produce subjective airway patency and antibacterial action."}, {"category": "Upper Airway Cleansing", "instruction": "Practice morning nasal saline irrigation (Jal Neti) using isotonic lukewarm sterile saline.", "scientific_rationale": "Removes entrapped particulate matter, allergens, and inflammatory cytokines from the sinonasal mucosa."}]');
