    daily_dose TEXT,
    composition TEXT,
    contraindications TEXT,
    monitoring TEXT,
    citations TEXT,
    mrp REAL,
    b2b_price REAL,
    regulatory_track TEXT,
    unani_name TEXT,
    is_hero_launch INTEGER DEFAULT 0
);
