INSERT INTO "master_products" VALUES('ZAY-009','NeuroShield-Rx™','','','ANDROLOGICAL',1,'Habb / Coated Micro-Tablets (60 Tabs)','1 tablet at night with 250ml warm saffron milk 2 hours after meal. Maximum 3 tablets per week.','[{"ingredient": "Zafran (Crocus sativus)", "amount_mg": 30, "standardization": "Crocin 3%"}, {"ingredient": "Jund Bedastar (Castoreum)", "amount_mg": 50, "standardization": "Purified Castorin Complex"}, {"ingredient": "Regmahi (Scincus officinalis)", "amount_mg": 50, "standardization": "Calcified Bio-Peptides"}, {"ingredient": "Kuchla Mudabbar (Purified Strychnos nux-vomica)", "amount_mg": 15, "standardization": "Strychnine 1.15%"}, {"ingredient": "Salab Misri (Orchis mascula)", "amount_mg": 300, "standardization": "Glucomannan 15%"}, {"ingredient": "Amber (Ambra grisea)", "amount_mg": 10, "standardization": "Ambrein 25%"}]','["Severe uncontrolled hypertension (>180/110 mmHg)", "Concurrent Nitrate therapy (Nitroglycerin, Isosorbide mononitrate)", "History of ventricular arrhythmias or recent myocardial infarction (<6 months)", "Pediatric age or female usage"]','["IIEF-5 Score", "Resting BP & Pulse", "Safety check every 30 days"]','["AYUSH Schedule E-1 Mandatory Monitoring Standard 2021"]',3400.0,1700.0,'AYUSH_SCHEDULE_E1_RX','Qurs-e-Taqwiyat-e-Quwwat-e-Baah',0);
INSERT INTO "master_products" VALUES('ZAY-010','SpermoPro™','','','ANDROLOGICAL',0,'Majoon / Oral Paste (30 Sachets)','10g in the morning on empty stomach with 250ml full-fat lukewarm milk for 90 days minimum','[{"ingredient": "Salab Panja (Dactylorhiza hatagirea)", "amount_mg": 300, "standardization": "Mucilaginous Glycoproteins 18%"}, {"ingredient": "Khulanjan (Alpinia galanga)", "amount_mg": 200, "standardization": "Galangin 3%"}, {"ingredient": "Behman Surkh (Salvia haematodes)", "amount_mg": 200, "standardization": "Salvianolic Acids 5%"}, {"ingredient": "Behman Safed (Centaurea behen)", "amount_mg": 200, "standardization": "Total Sterols 2%"}, {"ingredient": "Maghz-e-Badam (Prunus amygdalus)", "amount_mg": 400, "standardization": "Oleic & Linoleic Essential Lipids"}, {"ingredient": "Maghz-e-Pista (Pistacia vera)", "amount_mg": 200, "standardization": "Phytosterols & Tocopherols"}, {"ingredient": "Zafran (Crocus sativus)", "amount_mg": 15, "standardization": "Safranal 2%"}, {"ingredient": "Kushta Nuqra (Silver Calx)", "amount_mg": 30, "standardization": "Sub-micron Silver Nanoparticles"}]','["Non-obstructive Azoospermia with elevated FSH (>30 mIU/mL) - requires genetic karyotyping first", "Severe untreated varicocele Grade 3 (requires urological ligation evaluation)"]','["Semen Analysis (WHO 6th Edition) at baseline, 60 days, and 90 days", "Serum Testosterone, LH, FSH"]','["Andrologia 2020; Classical Unani spermatogenic formulation in idiopathic oligoasthenozoospermia"]',3800.0,1900.0,'AYUSH_CLASSICAL','Majoon-e-Taqwiyat-e-Mani-Shadeed',0);
