INSERT INTO "master_protocols" VALUES('P-01','Type 2 Diabetes Protocol','METABOLIC','','','','{"title": "Jigar Reset + Gut Axis", "duration_days": 30, "products": [{"name": "HepaClear", "dose": "4 caps/day", "timing": "AM empty + PM", "rationale": "Hepatic fat clearance, AMPK steatosis reversal, Kupffer anti-inflammation"}, {"name": "GutEase-IBS", "dose": "4 caps/day", "timing": "pre-meal", "rationale": "Gut microbiome reset (dysbiosis drives insulin resistance)"}], "diet": "Remove refined carbs, increase fibre; fasting window 14-10 hours; stop all processed sugar, maida, refined oil."}','{"title": "Glucose Control", "duration_days": 90, "products": [{"name": "DiabEase", "dose": "4 caps/day", "timing": "Pre-meal (lunch+dinner)", "rationale": "Berberine 600mg/day AMPK + Jamun alpha-glucosidase + Gurmar beta-cell regeneration"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Hepato-metabolic maintenance"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "bedtime", "rationale": "Cortisol-driven glucose dysregulation correction"}], "monitoring": "FBS monitoring every 2 weeks; HbA1c at 90 days."}','{"title": "Long-term Maintenance", "duration_days": "Ongoing", "products": [{"name": "Sugar Care", "dose": "4 caps/day", "timing": "Pre-meal", "rationale": "Lower dose glucose maintenance"}, {"name": "Men Daily / Women Daily", "dose": "2 caps/day", "timing": "AM with food", "rationale": "Daily micronutrient support"}, {"name": "HepaClear", "dose": "1 cap/day", "timing": "daily", "rationale": "Long-term NAFLD maintenance"}], "monitoring": "Annual: LFT, lipid panel, HbA1c, VitD3, serum zinc."}','{"core": ["DiabEase", "HepaClear"], "support": ["MindBalance", "GutEase-IBS"], "modulator": ["Sugar Care"]}','["FBS (2-weekly Phase 2)", "HbA1c (90 days)", "PP Glucose (90 days)", "LFT (0, 90 days)", "Lipid panel (90 days)", "Serum Insulin + HOMA-IR (0, 90 days)", "Vitamin D3 (baseline)"]','["NEVER replace prescribed antidiabetics.", "Monitor for hypoglycaemia especially if on sulphonylureas or insulin.", "Berberine + Metformin = additive \u2014 physician monitoring for lactic acidosis risk.", "Adjust Metformin dose only under physician supervision."]');
INSERT INTO "master_protocols" VALUES('P-02','Obesity & Metabolic Syndrome Protocol','METABOLIC','','','','{"title": "Liver + Gut Detox", "duration_days": 30, "products": [{"name": "HepaClear", "dose": "4 caps/day", "timing": "AM empty + PM", "rationale": "NAFLD reversal is prerequisite for weight loss"}, {"name": "GutEase-IBS", "dose": "4 caps/day", "timing": "pre-meal", "rationale": "Gut microbiome reset; L-Glutamine sealing leaky gut"}, {"name": "LipidClear", "dose": "1 cap/day", "timing": "morning with 250ml water", "rationale": "Initiate lipid normalisation"}], "diet": "Caloric deficit: 500 kcal below TDEE; Mediterranean-style diet; 16:8 IF."}','{"title": "Active Fat Mobilisation", "duration_days": 60, "products": [{"name": "MetaboBurn-M", "dose": "4 caps/day", "timing": "Pre-meal (3 times daily)", "rationale": "Green Coffee AMPK + Garcinia HCA lipogenesis block + Guggul FXR thermogenesis"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Hepatic support"}, {"name": "LipidClear", "dose": "2 caps/day", "timing": "full dose with water", "rationale": "Bile binding and lipid reduction"}, {"name": "MindBalance", "dose": "1-2 caps/day", "timing": "bedtime", "rationale": "Cortisol-driven abdominal obesity control"}], "exercise": "30 min brisk walk 5x/week minimum."}','{"title": "Weight Maintenance", "duration_days": "Ongoing", "products": [{"name": "MetaboBurn-M", "dose": "2 caps/day", "timing": "morning", "rationale": "Half dose maintenance"}, {"name": "HepaClear", "dose": "1 cap/day", "timing": "daily", "rationale": "Hepatic maintenance"}, {"name": "Sugar Care", "dose": "2 caps/day", "timing": "as needed", "rationale": "If metabolic syndrome persists"}], "monitoring": "Quarterly: lipid panel, FBS, LFT, waist circumference."}','{"core": ["MetaboBurn-M", "HepaClear", "LipidClear"], "support": ["GutEase-IBS", "MindBalance"], "modulator": ["Sugar Care"]}','["Weight + waist (monthly)", "Fasting lipid panel (45-day)", "FBS + HOMA-IR (0, 90)", "LFT (0, 90)", "BMI trend"]','["MetaboBurn-M is adjunct to caloric restriction \u2014 not standalone.", "Isabgol: 250ml water per dose mandatory.", "Monitor TSH at baseline (Guggul thyroid effect)."]');
INSERT INTO "master_protocols" VALUES('P-03','Dyslipidaemia & Lipid Management Protocol','METABOLIC','','','','{"title": "Hepatic Reset", "duration_days": 30, "products": [{"name": "HepaClear", "dose": "4 caps/day", "timing": "AM empty + PM", "rationale": "Liver dysfunction drives dyslipidemia"}, {"name": "DiabEase", "dose": "2 caps/day", "timing": "if T2DM comorbid", "rationale": "Insulin resistance drives VLDL output"}], "diet": "Remove trans fats, increase soluble fibre (Isabgol), omega-3 foods."}','{"title": "Active Lipid Management", "duration_days": 90, "products": [{"name": "LipidClear", "dose": "2 caps/day", "timing": "Empty stomach (AM+PM) with 250ml water", "rationale": "Guggul FXR+thyroid + Berberine PCSK9-like + Isabgol bile-binding + Artichoke Cynarin"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "Hepatic clearance continuation"}, {"name": "CardioGuard", "dose": "1-2 caps/day", "timing": "daily", "rationale": "If IHD or CVD risk present"}], "monitoring": "MANDATORY: 250ml water with LipidClear each dose."}','{"title": "Maintenance", "duration_days": "Ongoing", "products": [{"name": "LipidClear", "dose": "1-2 caps/day", "timing": "daily", "rationale": "Long-term lipid maintenance"}], "monitoring": "Annual lipid panel; LFT check."}','{"core": ["LipidClear", "HepaClear"], "support": ["CardioGuard", "DiabEase"], "modulator": ["MetaboBurn-M"]}','["Fasting lipid panel (0, 45, 90)", "LFT (0, 90)", "TSH (baseline and 90 days)", "FBS if DM comorbid"]','["LipidClear: 250ml water per dose mandatory (Isabgol obstruction risk).", "Monitor TSH \u2014 Guggul activates thyroid receptor.", "Continue statin if prescribed \u2014 additive lipid lowering."]');
INSERT INTO "master_protocols" VALUES('P-04','Hypertension Management Protocol','CARDIO','','','','{"title": "Sympathetic Calming", "duration_days": 30, "products": [{"name": "HyperCalm", "dose": "4 caps/day", "timing": "AM before food + PM before dinner", "rationale": "Sarpagandha sympatholysis + Arjun 200mg PDE + CoQ10 endothelial support"}, {"name": "MindBalance", "dose": "3 caps/day", "timing": "1 AM + 2 bedtime", "rationale": "HPA-cortisol driven HTN; GABA calming"}, {"name": "Sleep+Stress", "dose": "2 caps/day", "timing": "bedtime", "rationale": "Sleep quality critical for BP normalisation"}], "monitoring": "Monitor BP at home twice daily; log every reading."}','{"title": "Cardiovascular Reinforcement", "duration_days": 60, "products": [{"name": "HyperCalm", "dose": "4 caps/day", "timing": "AM+PM", "rationale": "Continued BP modulation"}, {"name": "CardioGuard", "dose": "2 caps/day", "timing": "AM warm milk + PM", "rationale": "Arjun cardiotonic + Nattokinase + CoQ10 endothelial + Shilajit"}, {"name": "LipidClear", "dose": "2 caps/day", "timing": "if dyslipidemia present", "rationale": "Atherosclerotic BP reduction"}], "diet": "DASH diet; sodium <2g/day; increase potassium foods; quit tobacco."}','{"title": "Long-term Cardiac Protection", "duration_days": "Ongoing", "products": [{"name": "CardioGuard", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Vascular elasticity and endothelial support"}, {"name": "HyperCalm", "dose": "2-4 caps/day", "timing": "ongoing Rx", "rationale": "AYUSH prescription"}], "monitoring": "Cardiologist review every 3-6 months; NEVER stop allopathic antihypertensives without clearance."}','{"core": ["HyperCalm", "CardioGuard"], "support": ["MindBalance", "LipidClear"], "modulator": ["Sleep+Stress"]}','["BP home monitoring daily", "ECG (0, 90 days)", "RFTs (0, 90)", "Serum electrolytes (90 days)", "Lipid panel (0, 90)", "Echocardiogram (annual)"]','["HyperCalm is PRESCRIPTION ONLY (Schedule E1 Sarpagandha).", "NEVER stop allopathic BP medications.", "BP monitoring 2x daily mandatory.", "If BP >180/110, immediate emergency cardiologist referral."]');
INSERT INTO "master_protocols" VALUES('P-05','Cardiac Support & IHD Protocol','CARDIO','','','','{"title": "Cardiac Foundation", "duration_days": 45, "products": [{"name": "CardioGuard", "dose": "2 caps/day", "timing": "AM warm milk + PM", "rationale": "Arjun 480mg/day PDE + CoQ10 80mg + Shilajit + Nattokinase fibrinolytic"}, {"name": "LipidClear", "dose": "2 caps/day", "timing": "empty stomach", "rationale": "LDL plaque management"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "Hepatic protection of lipid metabolism"}]}','{"title": "Full Cardiac Protocol", "duration_days": 90, "products": [{"name": "CardioGuard", "dose": "4 caps/day", "timing": "intensive", "rationale": "Full myocardial and mitochondrial support"}, {"name": "HyperCalm", "dose": "2 caps/day", "timing": "if hypertensive", "rationale": "Blood pressure reduction"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "Cardiac anxiety is common post-MI"}, {"name": "LipidClear", "dose": "2 caps/day", "timing": "continued", "rationale": "Plaque stabilisation"}], "monitoring": "INR monitoring if on warfarin (Nattokinase mild anticoagulant synergy)."}','{"title": "Lifelong Cardiac Maintenance", "duration_days": "Lifelong", "products": [{"name": "CardioGuard", "dose": "2 caps/day", "timing": "standard dose", "rationale": "Lifelong protective cardiotonic"}], "monitoring": "Annual: ECG, ECHO, lipid panel, RFTs; Cardiologist supervision mandatory."}','{"core": ["CardioGuard", "LipidClear"], "support": ["HyperCalm", "MindBalance"], "modulator": ["HepaClear"]}','["ECG (0, 90 days)", "ECHO (annual)", "Lipid panel (0, 45, 90)", "LFT (0, 90)", "INR if on warfarin", "Troponin/BNP if symptomatic"]','["CONTINUE ALL CARDIAC MEDICATIONS \u2014 never substitute.", "If on warfarin: INR monitoring (Nattokinase mild fibrinolytic synergy).", "Cardiologist supervision mandatory for IHD patients.", "Emergency symptoms (chest pain, dyspnoea): immediate hospital transfer."]');
INSERT INTO "master_protocols" VALUES('P-06','Stress & Anxiety Protocol','NEURO','','','','{"title": "HPA Axis Reset", "duration_days": 30, "products": [{"name": "MindBalance", "dose": "3 caps/day", "timing": "1 AM + 2 bedtime", "rationale": "Ashwagandha cortisol -27% + Zafran SSRI + L-Theanine"}, {"name": "Sleep+Stress", "dose": "3 caps/day", "timing": "1 AM + 2 bedtime", "rationale": "Phosphatidylserine cortisol blunting + Mg Glycinate GABA"}], "lifestyle": "Morning: avoid caffeine in first 2 hours; 10-min sunlight exposure; Evening: no screens 1 hour before bed."}','{"title": "Neurochemical Rebalancing", "duration_days": 60, "products": [{"name": "MindBalance", "dose": "3 caps/day", "timing": "continued", "rationale": "Brahmi GABA-B + Jatamansi MAO-B + Unnab GABA-A"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "If stress-related fatty liver signs (elevated ALT)"}], "exercise": "30-min walk daily (lowers cortisol); digital detox evenings."}','{"title": "Long-term Resilience", "duration_days": "Ongoing", "products": [{"name": "MindBalance", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Neuro-HPA reserve preservation"}, {"name": "Sleep+Stress", "dose": "1-2 caps/day", "timing": "as needed", "rationale": "PRN sleep support"}], "monitoring": "PHQ-9 + GAD-7 monthly \u2014 do not discontinue abruptly."}','{"core": ["MindBalance", "Sleep+Stress"], "support": ["HepaClear"]}','["PHQ-9 + GAD-7 monthly", "Cortisol AM (0, 90 days)", "TSH (anxiety mimics thyroid)", "Vitamin D3 (deficiency = anxiety)", "CBC (rule out anaemia)"]','["Do not replace prescribed psychiatric medications.", "Do not abruptly stop after 3+ months (gradual taper).", "If suicidal ideation present: immediate psychiatric referral.", "Ashwagandha: avoid in thyroid conditions on medication."]');
INSERT INTO "master_protocols" VALUES('P-07','Insomnia & Sleep Disorder Protocol','NEURO','','','','{"title": "Sleep Architecture Reset", "duration_days": 30, "products": [{"name": "Sleep+Stress", "dose": "3 caps/day", "timing": "1 AM (circadian anchor) + 2 caps 30 min bedtime", "rationale": "Mg Glycinate + Jatamansi + Valeriana GABA restoration"}, {"name": "MindBalance", "dose": "1 cap/day", "timing": "bedtime", "rationale": "If anxiety-driven insomnia"}], "hygiene": "Fixed wake time (7 days including weekends); no naps; dark+cool room; eliminate caffeine after 12 PM."}','{"title": "Deep Sleep Restoration", "duration_days": 60, "products": [{"name": "Sleep+Stress", "dose": "3 caps/day", "timing": "continued full dose", "rationale": "Neurochemical sleep maintenance"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "bedtime", "rationale": "Stress/anxiety overlay"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "If liver dysfunction contributing to sleep waking"}]}','{"title": "Maintenance", "duration_days": "3-6 months then taper", "products": [{"name": "Sleep+Stress", "dose": "1-2 caps/day", "timing": "bedtime", "rationale": "Gradual taper \u2014 not abrupt discontinuation"}], "monitoring": "PSG (polysomnography) if sleep apnoea suspected."}','{"core": ["Sleep+Stress", "MindBalance"], "support": ["HepaClear"]}','["Sleep diary (2 weeks baseline)", "Cortisol AM (if >20mcg/dL = HPA disruption)", "TSH (hypothyroid = insomnia)", "Ferritin (RLS component)", "VitD3"]','["Do not replace prescribed sleep medications immediately \u2014 gradual transition.", "Rule out sleep apnoea (PSG if snoring + daytime sleepiness).", "Jatamansi MAO-B inhibitor: caution with dopaminergic drugs."]');
INSERT INTO "master_protocols" VALUES('P-08','Asthma & Allergic Respiratory Protocol','RESPIRATORY','','','','{"title": "Mucociliary Restoration", "duration_days": 30, "products": [{"name": "LungEase", "dose": "4 caps/day", "timing": "2 AM + 2 bedtime", "rationale": "NAC mucolytic + Mulethi Glycyrrhizin + Kalonji TQ 5-LOX"}, {"name": "Immunity", "dose": "4 caps/day", "timing": "2+2", "rationale": "Elderberry antiviral + Beta-Glucan innate + Gilo T-cell"}], "vehicle": "Warm Arq-e-Mulethi with honey; avoid known allergens; indoor air purifier."}','{"title": "Anti-inflammatory + Antiviral Layer", "duration_days": 60, "products": [{"name": "LungEase", "dose": "4 caps/day", "timing": "continued", "rationale": "Tulsi COX-2 antiviral + Banafsha expectorant + Selenium GPx lung"}, {"name": "Immunity", "dose": "4 caps/day", "timing": "continued", "rationale": "Adaptive immunity reinforcement"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "If stress-triggered bronchospasm"}], "warning": "Continue prescribed inhalers \u2014 NEVER stop bronchodilators."}','{"title": "Seasonal Prevention", "duration_days": "Ongoing monsoon + winter", "products": [{"name": "LungEase", "dose": "2-4 caps/day", "timing": "dose by season", "rationale": "Seasonal mucosal defence"}, {"name": "Immunity", "dose": "2 caps/day", "timing": "year-round", "rationale": "Preventive immunity"}], "monitoring": "FEV1/FVC spirometry at 3 and 6 months."}','{"core": ["LungEase", "Immunity"], "support": ["MindBalance"]}','["Spirometry FEV1/FVC (0, 90 days)", "IgE total (0, 90)", "Eosinophil count", "Chest X-ray if COPD"]','["NEVER stop prescribed inhalers (bronchodilators are life-saving).", "LungEase is ADJUNCT to inhalers \u2014 not replacement.", "If acute attack: use reliever inhaler; do not rely on supplements in emergencies.", "Mulethi long-term: monitor BP in hypertensive patients."]');
INSERT INTO "master_protocols" VALUES('P-09','Joint Pain & Arthritis Protocol','JOINTS','','','','{"title": "Inflammatory Cascade Block", "duration_days": 30, "products": [{"name": "JointFree", "dose": "4 caps/day", "timing": "with food (AM+PM)", "rationale": "AKBA 5-LOX + Curcumin COX-2/NF-kB + Ashwagandha NF-kB (3 pathways)"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "If systemic inflammation (elevated CRP, ALT)"}, {"name": "UroClear", "dose": "6 caps/day", "timing": "in gout", "rationale": "Uricosuric effect + Potassium Citrate"}], "physical": "RICE protocol for acute joints; warm compress for chronic."}','{"title": "Cartilage Protection + Repair", "duration_days": 60, "products": [{"name": "JointFree", "dose": "4 caps/day", "timing": "continued", "rationale": "UC-II collagen 4th mechanism + Sandal Safaid TRPV1 analgesic"}, {"name": "Immunity", "dose": "2 caps/day", "timing": "daily", "rationale": "Systemic anti-inflammatory via Beta-Glucan + Quercetin"}], "diet": "Anti-inflammatory (turmeric milk, omega-3 fish, no nightshades for RA); Physiotherapy mandatory."}','{"title": "Maintenance & Prevention", "duration_days": "Ongoing", "products": [{"name": "JointFree", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Cartilage preservation and joint mobility"}], "monitoring": "Annual: uric acid (gout); CRP; X-ray; Body weight management."}','{"core": ["JointFree"], "support": ["HepaClear", "Immunity", "UroClear"]}','["CRP + ESR (0, 45, 90)", "Uric acid (gout)", "RF + anti-CCP (RA)", "WOMAC score (0, 90)", "X-ray joint (0, 6 months)"]','["JointFree with food (Curcumin+UC-II absorption).", "AKBA: Boswellia most adulterated botanical \u2014 verify HPLC certificate.", "For RA: JointFree is adjunct to DMARDs; do not stop DMARDs."]');
INSERT INTO "master_protocols" VALUES('P-10','Erectile Dysfunction Protocol','MALE','','','','{"title": "Root Cause Assessment + Neurochemical Reset", "duration_days": 30, "products": [{"name": "VigorX-ED", "dose": "4 caps PRN", "timing": "60 min before activity", "rationale": "Assess vascular response"}, {"name": "MindBalance", "dose": "3 caps/day", "timing": "daily", "rationale": "Psychogenic ED #1 cause India <45 yrs; Zafran SSRI + Ashwagandha HPA"}, {"name": "TestoVital Classic", "dose": "4 caps/day", "timing": "if low T documented", "rationale": "Androgenic priming"}], "diagnostics": "Doppler if vasculogenic suspected; Testosterone + Prolactin + PSA baseline."}','{"title": "Chronic Restoration Protocol", "duration_days": 90, "products": [{"name": "VigorX-ED", "dose": "8 caps/day", "timing": "4+4 chronic", "rationale": "Citrulline+L-Arg 1760mg/day NO + Tongkat Ali + Shilajit 480mg + Warq Tila"}, {"name": "TestoVital Classic", "dose": "8 caps/day", "timing": "4 AM fasting + 4 PM", "rationale": "Triple HPG axis restoration"}, {"name": "MindBalance", "dose": "3 caps/day", "timing": "continued", "rationale": "Anticipatory anxiety suppression"}], "lifestyle": "No tobacco, no alcohol (both destroy endothelial NO production)."}','{"title": "Maintenance", "duration_days": "Ongoing", "products": [{"name": "VigorX-ED", "dose": "PRN", "timing": "as needed", "rationale": "On-demand vascular support"}, {"name": "TestoVital Classic", "dose": "4 caps/day", "timing": "maintenance", "rationale": "HPG axis maintenance"}], "monitoring": "Annual: Testosterone + PSA + lipid panel."}','{"core": ["VigorX-ED", "TestoVital Classic"], "support": ["MindBalance"], "modulator": ["Night-One X Classic (PRN acute)"]}','["Testosterone (total+free)", "Prolactin", "LH+FSH", "PSA", "Fasting glucose+HOMA-IR", "Lipid panel", "Blood pressure"]','["Prescription-only (Poshida Amraz \u2014 AYUSH Rx).", "Rule out prostate pathology (PSA before prescribing).", "No alcohol + tobacco (most common iatrogenic ED cause).", "If on PDE5 inhibitors: inform prescriber before combining (additive vasodilation)."]');
INSERT INTO "master_protocols" VALUES('P-11','Male Infertility Protocol','MALE','','','','{"title": "Antioxidant + Testicular Environment", "duration_days": 30, "products": [{"name": "FertiMax-M", "dose": "8 caps/day", "timing": "4+4", "rationale": "CoQ10 480mg/day Cochrane + Lycopene testicular + Selenium GPx-5 + Ashwagandha"}, {"name": "SemenGuard", "dose": "4 caps/day", "timing": "if high DFI", "rationale": "Jatamansi neural axis + Post Akhrot DHA omega-3 + CoQ10"}], "lifestyle": "Remove: smoking (most damaging to sperm), alcohol, hot tubs, tight clothing; Baseline WHO 6th semen analysis + DFI."}','{"title": "Spermatogenesis Support", "duration_days": 60, "products": [{"name": "Fertility PRO", "dose": "5 caps/day", "timing": "2+1+2", "rationale": "Ashwagandha +167% sperm + Kaunch anti-prolactin + CoQ10 + Zinc"}, {"name": "FertiMax-M", "dose": "8 caps/day", "timing": "continued", "rationale": "Antioxidant protection"}, {"name": "TestoVital Classic", "dose": "4 caps/day", "timing": "if testosterone deficient", "rationale": "Leydig steroidogenesis support"}], "guideline": "Zinc-rich foods; Vit D sunlight; sleep 7-8 hours (90% testosterone secreted during sleep)."}','{"title": "Semen Analysis + Optimisation", "duration_days": "90-day checkpoint", "products": [{"name": "Fertility Moderate", "dose": "4 caps/day", "timing": "maintenance", "rationale": "Ongoing spermatogenic maintenance"}], "monitoring": "Repeat WHO semen analysis at 90 days; if improvement: continue 90 more days before IUI/IVF; both partners evaluated."}','{"core": ["Fertility PRO", "FertiMax-M"], "support": ["SemenGuard", "TestoVital Classic"]}','["WHO 6th semen analysis (0, 45, 90)", "DFI \u2014 DNA fragmentation index", "ROS assay semen", "FSH+LH+T+Prolactin+Estradiol (0, 90)", "Testicular Doppler if varicocele suspected", "Karyotype if severe (<5M/mL)"]','["90 days = ONE spermatogenesis cycle minimum.", "Both partners must be evaluated simultaneously.", "Varicocele: surgical correction if grade 2-3 before supplementation.", "If azoospermia: specialist evaluation first."]');
INSERT INTO "master_protocols" VALUES('P-12','Low Testosterone & Hypogonadism Protocol','MALE','','','','{"title": "HPG Axis Assessment + Initiation", "duration_days": 30, "products": [{"name": "TestoVital Classic", "dose": "8 caps/day", "timing": "4 AM fasting + 4 PM", "rationale": "Ashwagandha HPG + Tongkat Ali SHBG + Shilajit 520mg + Warq Tila"}, {"name": "VitD3", "dose": "4000 IU/day", "timing": "morning", "rationale": "Deficiency alone causes -20-30% T"}], "lifestyle": "Night sleep optimisation (90% testosterone secreted during deep sleep); Baseline full panel."}','{"title": "Full HPG Restoration", "duration_days": 90, "products": [{"name": "TestoVital Classic", "dose": "8 caps/day", "timing": "continued", "rationale": "Full HPG stimulation"}, {"name": "Fertility PRO", "dose": "4 caps/day", "timing": "daily", "rationale": "Kaunch L-DOPA LH pulsatile stimulation"}, {"name": "Men Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Daily zinc + VitD3 + CoQ10 maintenance"}], "exercise": "Resistance training: compound exercises 3x/week; remove alcohol, chronic stress, sleep deprivation."}','{"title": "Monitoring + Maintenance", "duration_days": "Ongoing", "products": [{"name": "TestoVital Classic", "dose": "4 caps/day", "timing": "maintenance", "rationale": "Endogenous testosterone maintenance"}], "monitoring": "Annual: T+LH+FSH; DEXA if osteopenia suspected; NEVER use exogenous testosterone without specialist."}','{"core": ["TestoVital Classic", "Men Daily"], "support": ["Fertility PRO", "MindBalance"]}','["Total T + Free T (0, 90 days AM 8-10 AM)", "LH + FSH", "SHBG", "Prolactin", "VitD3", "Cortisol", "DEXA (if >45 yrs or severe)"]','["NEVER use exogenous testosterone without specialist \u2014 permanently suppresses HPG.", "Testosterone RCT effects appear at 90 days minimum.", "If Prolactin >25: refer for MRI pituitary before TestoVital."]');
INSERT INTO "master_protocols" VALUES('P-13','Prostate Health Protocol (BPH / LUTS)','MALE','','','','{"title": "Baseline + Inflammation Control", "duration_days": 30, "products": [{"name": "ProstaGuard", "dose": "6 caps/day", "timing": "2+2+2", "rationale": "Pumpkin Seed 5-AR + AKBA 5-LOX + Lycopene + Curcumin NF-kB"}, {"name": "UroClear", "dose": "4 caps/day", "timing": "daily", "rationale": "Diuretic relief + Potassium Citrate urinary pH"}], "mandate": "MANDATORY: PSA test before prescribing (rule out prostate cancer); IPSS score at baseline."}','{"title": "Active BPH Management", "duration_days": 90, "products": [{"name": "ProstaGuard", "dose": "6 caps/day", "timing": "continued", "rationale": "Prostatic anti-proliferative maintenance"}, {"name": "Men Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Zinc and VitD3 for prostate health"}], "lifestyle": "Diet: lycopene-rich foods (tomatoes, watermelon); reduce red meat, dairy fat; Pelvic floor exercises (Kegel) daily."}','{"title": "Monitoring + Maintenance", "duration_days": "Ongoing", "products": [{"name": "ProstaGuard", "dose": "4 caps/day", "timing": "maintenance", "rationale": "Long-term IPSS control"}], "monitoring": "PSA every 6 months mandatory; Uroflowmetry annually; Urologist review annually."}','{"core": ["ProstaGuard", "UroClear"], "support": ["Men Daily"]}','["PSA (MANDATORY \u2014 0 and 6 months)", "IPSS score (0, 90)", "Uroflowmetry (0, 90)", "Serum creatinine", "Urinalysis", "Prostate-specific ultrasound"]','["PSA MONITORING MANDATORY \u2014 rule out prostate cancer before any prescribing.", "If PSA >4: urology referral mandatory.", "Urologist supervision required."]');
INSERT INTO "master_protocols" VALUES('P-14','PCOS Protocol','FEMALE','','','','{"title": "Insulin Resistance Root Correction", "duration_days": 30, "products": [{"name": "HepaClear", "dose": "4 caps/day", "timing": "AM empty + PM", "rationale": "Gut-liver-insulin axis reset; 80% PCOS = insulin resistance root"}, {"name": "CycloCare-PCOS", "dose": "10 caps/day", "timing": "5+5", "rationale": "Myo+DCI Inositol 40:1 + Gurmar insulin + Dalchini MHCP"}], "diet": "Low GI (<55 GI foods); Mediterranean; 16:8 fasting optional; Exercise: HIIT 3x/week."}','{"title": "Hormonal Axis Correction", "duration_days": 90, "products": [{"name": "CycloCare-PCOS", "dose": "10 caps/day", "timing": "continued", "rationale": "Gokshura LH surge (67-78% ovulation RCT) + Shatavari FSH/LH + Zafran anti-androgenic"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "HPA-adrenal androgen excess"}, {"name": "FertiliWomen", "dose": "8 caps/day", "timing": "if fertility goal", "rationale": "CoQ10 480mg/day oocyte + 5-MTHF"}], "contraindication": "CONTRAINDICATED IN PREGNANCY: Zafran emmenagogue."}','{"title": "Cycle Regularisation Maintenance", "duration_days": "3-6 months", "products": [{"name": "CycloCare-PCOS", "dose": "4-6 caps/day", "timing": "maintenance", "rationale": "Cycle maintenance"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Micronutrient maintenance"}], "monitoring": "Menstrual cycle diary tracking; LH+FSH+AMH+Testosterone+HOMA-IR 3-monthly; Repeat pelvic USG at 6 months."}','{"core": ["CycloCare-PCOS", "HepaClear"], "support": ["MindBalance", "FertiliWomen"], "modulator": ["Women Daily"]}','["LH+FSH ratio (LH>2:1 FSH = PCOS marker)", "AMH (ovarian reserve)", "Total T+SHBG+FAI", "HOMA-IR+fasting insulin", "TSH (thyroid comorbid)", "Pelvic USG (0, 6 months)"]','["CONTRAINDICATED IN PREGNANCY \u2014 Zafran emmenagogue; confirm negative pregnancy test before prescribing.", "PCOS + insulin resistance: lifestyle intervention equally important as supplements.", "If fertility goal: gynaecologist co-management mandatory."]');
INSERT INTO "master_protocols" VALUES('P-15','Leucorrhoea Protocol','FEMALE','','','','{"title": "Antimicrobial + Astringent", "duration_days": 30, "products": [{"name": "LeucoClear", "dose": "8 caps/day", "timing": "2+2+2+2", "rationale": "L. acidophilus 3B CFU + Mochras tannin astringent + Gulnaar Punicalagin anti-Candida"}, {"name": "FemCare-L", "dose": "4 caps/day", "timing": "2+2", "rationale": "Neem Nimbin antibacterial + Shatavari uterine tonic + Iron Bisglycinate"}], "hygiene": "Maintain vaginal hygiene: pH-balanced wash only; no douching; Continue prescribed antifungal/antibacterial if active infection."}','{"title": "Microbiome Restoration", "duration_days": 60, "products": [{"name": "LeucoClear", "dose": "8 caps/day", "timing": "continued", "rationale": "L. acidophilus establishes vaginal Lactobacillus dominance"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Nutritional support; iron+B12+VitD3"}], "monitoring": "pH test strips: aim for vaginal pH <4.5; anaemia correction."}','{"title": "Prevention", "duration_days": "3-6 months", "products": [{"name": "LeucoClear", "dose": "4 caps/day", "timing": "maintenance", "rationale": "Flora preservation"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "ongoing", "rationale": "Nutritional foundation"}], "monitoring": "HVS culture at 3 months to confirm microbiome normalisation."}','{"core": ["LeucoClear", "FemCare-L"], "support": ["Women Daily"], "modulator": ["HepaClear"]}','["HVS culture+sensitivity (0, 90)", "Vaginal pH (weekly self-monitoring)", "Haemoglobin+ferritin", "Blood glucose (diabetes increases infection risk)"]','["Active Candida or BV: complete prescribed course first; LeucoClear is adjunct.", "Refrigerated storage mandatory for probiotic viability."]');
INSERT INTO "master_protocols" VALUES('P-16','Menstrual Health Protocol (Dysmenorrhoea / Menorrhagia)','FEMALE','','','','{"title": "Hormonal Balance", "duration_days": 30, "products": [{"name": "UterTone", "dose": "6 caps/day", "timing": "2+2+2", "rationale": "Vitex Chasteberry prolactin reduction (6 RCTs PMS)"}, {"name": "FemCare-L", "dose": "4 caps/day", "timing": "2+2", "rationale": "Shatavari uterine tonic + Iron Bisglycinate (menorrhagia anaemia)"}], "regimen": "Day 1-5 (menstrual): hot water bottle, ginger tea, light movement; Day 15-28 (luteal): Vitex acts on prolactin reduction in this phase."}','{"title": "Cycle Regularisation", "duration_days": 60, "products": [{"name": "UterTone", "dose": "6 caps/day", "timing": "continued + 5-MTHF", "rationale": "Methylation for endometrial repair"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "HPA-adrenal driven cycle disruption; PMDD component"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "Hepatic oestrogen metabolism (impaired liver = oestrogen dominance)"}], "diet": "Omega-3 foods: salmon, flaxseed (PGE2 reduction = less dysmenorrhoea)."}','{"title": "Maintenance", "duration_days": "3-6 months", "products": [{"name": "UterTone", "dose": "2-4 caps/day", "timing": "maintenance", "rationale": "Luteal phase support"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "ongoing", "rationale": "Nutritional support"}], "monitoring": "Serum progesterone day 21 monitoring; if endometriosis suspected: gynaecologist ultrasound."}','{"core": ["UterTone", "FemCare-L"], "support": ["MindBalance", "HepaClear"], "modulator": ["Women Daily"]}','["Serum progesterone (day 21)", "Prolactin", "FSH+LH (day 2-3)", "Haemoglobin+ferritin", "TSH", "Pelvic USG (endometriosis, fibroid)"]','["PHYSICIAN MONITORING MANDATORY for UterTone.", "Not for use in pregnancy (Zafran emmenagogue in UterTone).", "If menorrhagia >80mL/cycle: gynaecologist mandatory.", "Vitex: may interac