INSERT INTO "master_protocols" VALUES('P-17','Menopause Management Protocol','FEMALE','','','','{"title": "Vasomotor Symptom Control", "duration_days": 45, "products": [{"name": "MenoPease", "dose": "10 caps/day", "timing": "5+5 with food", "rationale": "Cimicifuga 150mg/day 5-HT7 (Cochrane hot flush RCTs) + Pueraria Miroestrol ER-beta"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Calcium + VitD3 + iron + B12 foundational"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "bedtime", "rationale": "Menopausal mood disruption; Ashwagandha HPA"}]}','{"title": "Bone + Cardiovascular Protection", "duration_days": 90, "products": [{"name": "MenoPease", "dose": "10 caps/day", "timing": "continued", "rationale": "Coral Calcium + VitD3 + Shallaki AKBA anti-osteoclast bone stack"}, {"name": "CardioGuard", "dose": "2 caps/day", "timing": "daily", "rationale": "Post-menopausal CVD risk doubles; CoQ10+Shilajit+Arjun cardiac"}, {"name": "LipidClear", "dose": "2 caps/day", "timing": "if lipid abnormality", "rationale": "Post-menopausal LDL rise is common"}], "exercise": "Weight-bearing exercise: walking + strength 4x/week (bone density)."}','{"title": "Lifelong Maintenance", "duration_days": "Lifelong", "products": [{"name": "MenoPease", "dose": "4-6 caps/day", "timing": "maintenance", "rationale": "Endocrine balance"}, {"name": "Women Daily", "dose": "2 caps/day", "timing": "ongoing", "rationale": "Bone mineral support"}], "monitoring": "DEXA bone density at 1 year and every 2 years; Continue HRT if prescribed \u2014 MenoPease is adjunct."}','{"core": ["MenoPease", "Women Daily"], "support": ["CardioGuard", "MindBalance", "LipidClear"]}','["FSH+LH+E2 (menopausal status)", "DEXA (0, 12 months)", "Lipid panel (0, 6 months)", "Blood pressure", "TSH", "Calcium+VitD3"]','["MenoPease is ADJUNCT to HRT \u2014 never substitute without gynaecologist.", "Pueraria mirifica: potent phytoestrogen \u2014 gynaecologist supervision.", "Cimicifuga: 150mg/day (FSSAI compliant dose)."]');
INSERT INTO "master_protocols" VALUES('P-18','Female Fertility Protocol','FEMALE','','','','{"title": "Hormonal Baseline + Oocyte Quality", "duration_days": 30, "products": [{"name": "FertiliWomen", "dose": "8 caps/day", "timing": "4+4", "rationale": "CoQ10 480mg/day oocyte mitochondrial + Gokshura LH surge + 5-MTHF"}, {"name": "CycloCare-PCOS", "dose": "10 caps/day", "timing": "if PCOS infertility", "rationale": "Myo+DCI 40:1 + Gokshura + Gurmar insulin"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "daily", "rationale": "Hepatic oestrogen metabolism"}], "diagnostics": "Baseline: AMH, AFC, FSH, LH, E2, prolactin, TSH, HOMA-IR; at least 2 cycles before conception attempt."}','{"title": "Cycle Support + Endometrial Preparation", "duration_days": 90, "products": [{"name": "FertiliWomen", "dose": "8 caps/day", "timing": "continued", "rationale": "Shatavari endometrial thickening + Zafran uterine blood flow"}, {"name": "UterTone", "dose": "4 caps/day", "timing": "luteal phase", "rationale": "Vitex progesterone support + 5-MTHF endometrial DNA"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "bedtime", "rationale": "Fertility anxiety (cortisol impairs FSH sensitivity)"}], "mandate": "Both partners evaluated simultaneously."}','{"title": "IVF/IUI Support (if ART)", "duration_days": "During stimulation", "products": [{"name": "FertiliWomen", "dose": "8 caps/day", "timing": "through stimulation phase", "rationale": "CoQ10 oocyte protection"}], "critical_rule": "Stop Zafran-containing products on confirmed pregnancy; continue 5-MTHF + CoQ10 + Shatavari through first trimester (gynaecologist approval)."}','{"core": ["FertiliWomen", "CycloCare-PCOS"], "support": ["UterTone", "MindBalance", "HepaClear"], "modulator": ["Women Daily"]}','["AMH+AFC (ovarian reserve)", "FSH+LH+E2 (day 2-3)", "Progesterone (day 21)", "Prolactin+TSH+Insulin", "Both partner: semen analysis", "Pelvic USG (antral follicle count)"]','["GYNAECOLOGIST MONITORING MANDATORY.", "Stop Zafran products on confirmed pregnancy.", "Both partners must be evaluated \u2014 50% infertility is male factor.", "IVF: inform reproductive endocrinologist of all supplements before stimulation."]');
INSERT INTO "master_protocols" VALUES('P-19','Immunity & Infection Prevention Protocol','GENERAL','','','','{"title": "Innate Immunity Priming", "duration_days": 30, "products": [{"name": "Immunity", "dose": "4 caps/day", "timing": "2+2", "rationale": "Elderberry neuraminidase + Beta-Glucan Dectin-1 macrophage + Gilo T-cell + Kalonji TQ"}, {"name": "LungEase", "dose": "2 caps/day", "timing": "daily", "rationale": "Respiratory mucociliary barrier (first line of defence)"}], "check": "Vitamin D3 check (VD3 deficiency = #1 immune vulnerability in India)."}','{"title": "Adaptive Immunity + Antiviral", "duration_days": 60, "products": [{"name": "Immunity", "dose": "4 caps/day", "timing": "continued full dose", "rationale": "Tulsi COX-2 antiviral + Zinc ionophore + Ashwagandha T-cell modulation"}, {"name": "LungEase", "dose": "2 caps/day", "timing": "continued", "rationale": "NAC mucolytic + Selenium GPx lung"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "if liver impaired", "rationale": "Immune-liver connection"}], "lifestyle": "Sleep 7-8 hours (NK cell activity declines 70% with sleep deprivation)."}','{"title": "Seasonal Maintenance", "duration_days": "Year-round / seasonal peaks", "products": [{"name": "Immunity", "dose": "2 caps/day", "timing": "maintenance; 4 in flu season", "rationale": "Ongoing immune surveillance"}], "monitoring": "Annual CBC; continue vaccinations."}','{"core": ["Immunity", "LungEase"], "support": ["HepaClear"]}','["CBC with differential (0, 90)", "IgE total (allergy component)", "VitD3 (baseline)", "TSH (thyroid immune link)"]','["Not a vaccine substitute.", "Continue prescribed immunosuppressants if applicable.", "Active infection: continue antibiotics; Immunity is adjunct prevention."]');
INSERT INTO "master_protocols" VALUES('P-20','IBS & Gut Health Protocol','GENERAL','','','','{"title": "Gut Barrier Repair", "duration_days": 30, "products": [{"name": "GutEase-IBS", "dose": "6 caps/day", "timing": "2+2+2 pre-meal", "rationale": "L-Glutamine tight junctions + Peppermint beads enteric smooth muscle + Synbiotic 5B CFU"}, {"name": "HepaClear", "dose": "4 caps/day", "timing": "AM empty + PM", "rationale": "Gut-liver axis restoration; Kaasni inulin prebiotic"}], "mandate": "Isabgol with 250ml water (MANDATORY each dose); Remove FODMAPs, refined sugar, alcohol (IBS triggers)."}','{"title": "Microbiome Diversification", "duration_days": 60, "products": [{"name": "GutEase-IBS", "dose": "6 caps/day", "timing": "continued", "rationale": "Kaasni inulin feeds Bifidobacterium; Probiotic 5B CFU re-colonises"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "Gut-brain axis (IBS has 50% psychiatric comorbidity)"}], "diet": "Fermented foods: yoghurt, kefir, fermented vegetables; identify personal trigger foods (food diary)."}','{"title": "Maintenance + Prevention", "duration_days": "Ongoing", "products": [{"name": "GutEase-IBS", "dose": "3 caps/day", "timing": "maintenance", "rationale": "Gut mucosal stability"}], "monitoring": "Bristol stool scale monthly self-monitoring; IBS-SSS score at 3 and 6 months."}','{"core": ["GutEase-IBS", "HepaClear"], "support": ["MindBalance"]}','["Colonoscopy (rule out IBD \u2014 mandatory before supplement prescribing)", "IBS-SSS score (0, 90)", "Stool culture (rule out SIBO)", "Lactulose/mannitol ratio (leaky gut)"]','["Rule out IBD (Crohns, UC) before prescribing \u2014 colonoscopy mandatory.", "GutEase is NOT for IBD management.", "250ml water per dose with Isabgol \u2014 obstruction risk without water.", "Peppermint: enteric-coated beads only; do NOT open capsule."]');
INSERT INTO "master_protocols" VALUES('P-21','Hair Loss Protocol','GENERAL','','','','{"title": "Root Cause Investigation + Foundation", "duration_days": 30, "products": [{"name": "HairRoot-X", "dose": "4 caps/day", "timing": "2+2 with food", "rationale": "Bhringraj Wedelolactone 2% Wnt pathway + Pumpkin Seed 5-AR + Zinc DHT block"}, {"name": "MindBalance", "dose": "2 caps/day", "timing": "daily", "rationale": "Telogen effluvium is often stress-triggered cortisol elevation"}], "diagnostics": "Rule out: hypothyroid (TSH), iron deficiency (ferritin <50), VitD3 deficiency; Baseline trichoscopy."}','{"title": "DHT Block + Follicle Activation", "duration_days": 90, "products": [{"name": "HairRoot-X", "dose": "4 caps/day", "timing": "continued", "rationale": "Biotin 5mg + Selenium follicle GPx + Bhringraj Wnt stem cell activation"}, {"name": "Women Daily / Men Daily", "dose": "2 caps/day", "timing": "with food", "rationale": "Daily micronutrient base"}, {"name": "HepaClear", "dose": "2 caps/day", "timing": "if elevated ALT", "rationale": "NAFLD drives androgen excess in female AGA"}, {"name": "CycloCare-PCOS", "dose": "10 caps/day", "timing": "if PCOS-related AGA", "rationale": "Insulin-androgen axis correction in females"}]}','{"title": "Long-term Maintenance", "duration_days": "6-12 months", "products": [{"name": "HairRoot-X", "dose": "2 caps/day", "timing": "maintenance", "rationale": "Follicle density preservation"}], "routine": "Trichoscopy at 3 and 6 months; Scalp massage daily (5 min) \u2014 VEGF stimulation proven in RCT."}','{"core": ["HairRoot-X"], "support": ["MindBalance", "HepaClear"], "modulator": ["CycloCare-PCOS (female PCOS-AGA)", "Women Daily / Men Daily"]}','["TSH (hypothyroid AGA)", "Ferritin+serum iron (iron-deficiency AGA)", "VitD3", "DHEAS+T+SHBG (androgenic)", "Trichoscopy (0, 3, 6 months)"]','["Minimum 6 months for meaningful hair cycle response.", "Rule out alopecia areata (autoimmune) and tinea capitis (fungal) before prescribing.", "Bhringraj: Wedelolactone >2% mandatory \u2014 unstandardised has zero efficacy."]');
CREATE TABLE mizaj_assessments (
    id TEXT PRIMARY KEY,
    patient_id TEXT NOT NULL,
    encounter_id TEXT,
    ten_ajnas_vectors_json TEXT NOT NULL,      -- Vector scores across Dam, Balgham, Safra, Sauda
    questionnaire_responses_json TEXT,
    dominant_temperament TEXT NOT NULL,       -- DAM, BALGHAM, SAFRA, SAUDA, COMPOUND, or INSUFFICIENT_DATA
    dyscrasia_degree INTEGER DEFAULT 1,       -- 1 to 4
    contradiction_flags_json TEXT DEFAULT "[]",
    clinician_confirmed BOOLEAN DEFAULT 0,
    status TEXT NOT NULL,                     -- COMPLETED, INSUFFICIENT_DATA, CLINICIAN_OVERRIDDEN
    assessed_by TEXT NOT NULL,
    assessed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(patient_id) REFERENCES patients(id)
);
CREATE TABLE mufradat_twelve_gates (
    id TEXT PRIMARY KEY,
    zmf_id TEXT NOT NULL,
    gate_number INTEGER NOT NULL,
    gate_name TEXT NOT NULL,
    signed_by TEXT NOT NULL,
    signed_at TEXT NOT NULL,
    notes TEXT,
    evidence_hash TEXT,
    UNIQUE(zmf_id, gate_number)
);
